    for (const events of [ar4, wheeled, stretch] as unknown as JobEvent[][]) {
      for (const e of events) {
        if (e.type !== 'stage') continue
        expect(STAGE_ORDER.includes(e.data.stage) || TERMINAL_STAGES.has(e.data.stage)).toBe(true)
      }
    }
  })
})

