/** The report tab: one page from the decision down to the evidence, with a contents list. */
export function Report({ job, onboarded, card, modelNotes }: Props) {
  const page = useRef<HTMLDivElement>(null)
  const deep = deepLineComparison(job)
  const sections: [string, string, boolean][] = [
    ['summary', 'Summary', true],
    ['deep', deep ? `Deep line: ${deep.part}` : 'Deep line', deep !== null],
    ['actions', 'Action plan', job.recommendations.length > 0],
    ['supply', 'Supply map', job.riskLines.length > 0],
    ['requirements', 'Your requirements', true],
    ['evidence', 'Evidence', job.claims.length > 0 || job.runOrder.length > 0],
  ]
  const go = (id: string) => page.current?.querySelector(`#${id}`)?.scrollIntoView({ behavior: 'smooth', block: 'start' })
  return (
    <div className="page report-page" ref={page}>
      <nav className="toc" aria-label="Report sections">
        {sections
          .filter(([, , on]) => on)
          .map(([id, title]) => (
            <button key={id} type="button" onClick={() => go(id)}>
              {title}
            </button>
          ))}
      </nav>
      <article className="report-body">
        <Summary job={job} deep={deep} />
        {deep && <DeepLineSection job={job} deep={deep} modelNotes={modelNotes} />}
        {job.recommendations.length > 0 && <ActionPlan job={job} />}
        {job.riskLines.length > 0 && <SupplyMap job={job} />}
        <Requirements job={job} onboarded={onboarded} card={card} />
        {(job.claims.length > 0 || job.runOrder.length > 0) && <Evidence job={job} />}
      </article>
    </div>
  )
}
import { levelAccuracy } from '../accuracy'
import type { Level, Priority } from '../events'

export function LevelChip({ level, title, children }: { level: Level; title?: string; children?: string }) {
  return (
    <span className={`chip level-${level}`} title={title}>
      <span className={`dot ${levelAccuracy(level)}`} />
      {children ?? level}
    </span>
  )
}

/** The 0-9 priority as a chip; a range means some evidence is missing. */
export function PriorityChip({ priority }: { priority: Priority }) {
  const range = priority.hi > priority.lo ? `${priority.lo}–${priority.hi}` : `${priority.lo}`
  return <LevelChip level={priority.level}>{`${priority.level} ${range}/9`}</LevelChip>
}
// One color scale for how far to trust a value or a result: green (hi), yellow (mid), red (lo).
// Grey ('none') is for things not assessed yet.

import type { Level, Outcome } from './events'
import type { Source } from './onboarding/intake'

export type Accuracy = 'hi' | 'mid' | 'lo' | 'none'

/** A number on the review screen: the user's words or files are high, an estimate mid, a default low. */
export function specAccuracy(source: Source, evidence: string | null): Accuracy {
  if (source === 'default') return 'lo'
  if (evidence?.startsWith('estimate')) return 'mid'
  return 'hi'
}

/** An agent run: verified source green, partial yellow, anything that failed or was blocked red. */
export function outcomeAccuracy(outcome: Outcome | null): Accuracy {
  if (outcome === null) return 'none'
  if (outcome === 'success') return 'hi'
  if (outcome === 'incomplete') return 'mid'
  return 'lo'
}

/** A supply-risk level: low risk reads green, high risk red. */
export function levelAccuracy(level: Level): Accuracy {
  return ({ low: 'hi', medium: 'mid', high: 'lo', unknown: 'none' } as const)[level]
}

